    markers = []
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != 8 and val != 0:
                markers.append((r, c))

    # Calculate the diagonal intersection point where marker diagonal hits wall
    # Diagnose the simplest approach: find where marker direction would hit wall col
    # and start 3s one cell before that point

    if markers and max_c >= 0:
        # Determine wall side (left or right edge)
        wall_edge = max_c if markers[0][1] > min_c else min_c

        # Consider marker direction: find the "extreme" marker position
        extreme_marker = markers[0]
        for r, c in markers:
            if r > extreme_marker[0] or (r == extreme_marker[0] and c > extreme_marker[1]):
                extreme_marker = (r, c)

        # Estimate intersection row assuming 45° diagonal
        # From extreme marker to wall edge
        dr = extreme_marker[0] - min_r  # rows from top
        dc = extreme_marker[1] - wall_edge

        # If marked are to the right (dc > 0), diagonal goes left toward wall at -45° slope
